class AuthService {
  async login(input) {
    const user = await User.findOne({ email: input.email.toLowerCase() }).select("+password").populate("role");
    if (!user) {
      throw Object.assign(new Error("Invalid email or password"), { statusCode: 401 });
    }
    if (user.status === "inactive") {
      throw Object.assign(new Error("Your account has been deactivated"), { statusCode: 403 });
    }
    const isPasswordValid = await user.comparePassword(input.password);
    if (!isPasswordValid) {
      throw Object.assign(new Error("Invalid email or password"), { statusCode: 401 });
    }
    const payload = {
      userId: user._id.toString(),
      email: user.email,
      roleId: user.role._id.toString()
    };
    const accessToken = signAccessToken(payload);
    const refreshToken = signRefreshToken(payload);
    const userObj = user.toJSON();
    return { accessToken, refreshToken, user: userObj };
  }
  async refreshToken(token) {
    const decoded = verifyRefreshToken(token);
    const user = await User.findById(decoded.userId).select("status");
    if (!user || user.status === "inactive") {
      throw Object.assign(new Error("Invalid refresh token"), { statusCode: 401 });
    }
    const payload = {
      userId: decoded.userId,
      email: decoded.email,
      roleId: decoded.roleId
    };
    const accessToken = signAccessToken(payload);
    const newRefreshToken = signRefreshToken(payload);
    return { accessToken, refreshToken: newRefreshToken };
  }
  async getProfile(userId) {
    const user = await User.findById(userId).populate("role");
    if (!user) {
      throw Object.assign(new Error("User not found"), { statusCode: 404 });
    }
    return user;
  }
  async changePassword(userId, input) {
    const user = await User.findById(userId).select("+password");
    if (!user) {
      throw Object.assign(new Error("User not found"), { statusCode: 404 });
    }
    const isValid = await user.comparePassword(input.currentPassword);
    if (!isValid) {
      throw Object.assign(new Error("Current password is incorrect"), { statusCode: 400 });
    }
    user.password = input.newPassword;
    await user.save();
    return { message: "Password changed successfully" };
  }
}

