var BLUE = "#3b82f6";
var GRAY = "#64748b";
var DARK = "#0f172a";
var LIGHT = "#f1f5f9";
var WHITE = "#ffffff";
var AMBER = "#f59e0b";
function pdfTable(doc2, headers, colW, rows, startX, startY, rowH = 20) {
  const totalW = colW.reduce((a, b) => a + b, 0);
  const pageBottom = doc2.page.height - 50;
  const pageTop = 40;
  function drawHeader(y) {
    doc2.rect(startX, y, totalW, rowH).fill(BLUE);
    doc2.fillColor(WHITE).font("Helvetica-Bold").fontSize(7.5);
    let x = startX;
    headers.forEach((h, i) => {
      doc2.text(h, x + 4, y + 6, { width: colW[i] - 6, align: i === 0 ? "left" : "center" });
      x += colW[i];
    });
    return y + rowH;
  }
  let currentY = drawHeader(startY);
  doc2.font("Helvetica").fontSize(7).fillColor(DARK);
  rows.forEach((row, ri) => {
    if (currentY + rowH > pageBottom) {
      doc2.addPage();
      currentY = drawHeader(pageTop);
    }
    const bg = ri % 2 === 0 ? WHITE : LIGHT;
    doc2.rect(startX, currentY, totalW, rowH).fill(bg);
    doc2.fillColor(DARK);
    let cx2 = startX;
    row.forEach((cell, ci) => {
      doc2.text(String(cell ?? "-"), cx2 + 4, currentY + 6, {
        width: colW[ci] - 6,
        align: ci === 0 ? "left" : "center"
      });
      cx2 += colW[ci];
    });
    doc2.rect(startX, currentY, totalW, rowH).stroke("#e2e8f0");
    currentY += rowH;
  });
  return currentY;
}
