var io2;
function initSocket(httpServer) {
  io2 = new Server(httpServer, {
    cors: {
      origin: env.CLIENT_URL,
      credentials: true
    },
    transports: ["websocket", "polling"]
  });
  io2.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token)
      return next(new Error("Authentication required"));
    try {
      const decoded = verifyAccessToken(token);
      socket.data.userId = decoded.userId;
      next();
    } catch {
      next(new Error("Invalid token"));
    }
  });
  io2.on("connection", (socket) => {
    const userId = socket.data.userId;
    if (userId) {
      socket.join(`user:${userId}`);
      console.log(`\uD83D\uDFE2 Socket connected: userId=${userId} socketId=${socket.id}`);
    }
    socket.on("disconnect", () => {
      console.log(`\uD83D\uDD34 Socket disconnected: userId=${userId} socketId=${socket.id}`);
    });
    socket.on("join:team", (teamId) => {
      if (typeof teamId === "string" && teamId.length > 0) {
        socket.join(`team:${teamId}`);
        console.log(`\uD83D\uDCCC User ${userId} joined team room: ${teamId}`);
      }
    });
    socket.on("leave:team", (teamId) => {
      if (typeof teamId === "string") {
        socket.leave(`team:${teamId}`);
      }
    });
  });
  console.log("\uD83D\uDD0C Socket.IO initialized");
  return io2;
}
function emitTeamUpdate(teamId, item) {
  if (!io2)
    return;
  io2.to(`team:${teamId}`).emit("team:update", { teamId, item });
}
function emitToUser(userId, event, payload) {
  if (!io2)
    return;
  const room = `user:${userId}`;
  const sockets = io2.sockets.adapter.rooms.get(room);
  console.log(`\uD83D\uDCE4 emitToUser \u2192 room=${room} sockets=${sockets?.size ?? 0} event=${event}`);
  io2.to(room).emit(event, payload);
}

