var uploadLeads = async (req, res, next) => {
  try {
    const file2 = req.file;
    if (!file2) {
      sendError(res, "No file uploaded", 400);
      return;
    }
    const allowedMimetypes = [
      "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      "application/vnd.ms-excel",
      "text/csv",
      "application/csv"
    ];
    if (!allowedMimetypes.includes(file2.mimetype) && !file2.originalname.match(/\.(xlsx|xls|csv)$/i)) {
      sendError(res, "Invalid file type. Please upload an xlsx, xls, or csv file.", 400);
      return;
    }
    const parseResult = await excelService.parseFile(file2.buffer, file2.mimetype);
    if (parseResult.valid.length === 0 && parseResult.invalid.length > 0) {
      sendError(res, "No valid leads found in the file", 400, {
        invalid: parseResult.invalid
      });
      return;
    }
    const reporterId = req.user.userId;
    let bulkResult = { inserted: [], skipped: 0, skippedPhones: [] };
    if (parseResult.valid.length > 0) {
      bulkResult = await leadService2.bulkCreateLeads(parseResult.valid, reporterId);
    }
    const createdLeads = bulkResult.inserted;
    let teamIds;
    try {
      if (req.body.teamIds) {
        const parsed2 = JSON.parse(req.body.teamIds);
        if (Array.isArray(parsed2))
          teamIds = parsed2.filter((id) => typeof id === "string");
      }
    } catch {}
    let memberOverrides;
    try {
      if (req.body.memberOverrides) {
        const parsed2 = JSON.parse(req.body.memberOverrides);
        if (parsed2 && typeof parsed2 === "object" && !Array.isArray(parsed2)) {
          memberOverrides = parsed2;
        }
      }
    } catch {}
    let assignmentResult = {
      assigned: 0,
      results: []
    };
    if (createdLeads.length > 0) {
      try {
        const leadIds = createdLeads.map((l) => l._id.toString());
        assignmentResult = await leadService2.autoAssignLeads(leadIds, teamIds, memberOverrides);
      } catch {}
    }
    sendSuccess(res, "Leads uploaded successfully", {
      total: parseResult.valid.length + parseResult.invalid.length,
      created: createdLeads.length,
      skipped: bulkResult.skipped,
      skippedPhones: bulkResult.skippedPhones,
      assigned: assignmentResult.assigned,
      invalid: parseResult.invalid.length,
      invalidDetails: parseResult.invalid
    }, 201);
  } catch (error48) {
    next(error48);
  }
};
