async function getTeamMemberReport(req, res, next) {
  try {
    const teamId = req.params.id;
    const { dateFrom, dateTo } = req.query;
    if (!import_mongoose12.default.isValidObjectId(teamId)) {
      sendError(res, "Invalid team id", 400);
      return;
    }
    const dateFilter = {};
    if (dateFrom)
      dateFilter.$gte = new Date(dateFrom + "T00:00:00.000+05:30");
    if (dateTo)
      dateFilter.$lte = new Date(dateTo + "T23:59:59.999+05:30");
    const matchFilter = {
      team: new import_mongoose12.default.Types.ObjectId(teamId)
    };
    if (dateFrom || dateTo)
      matchFilter.createdAt = dateFilter;
    const statusSums = {};
    for (const s of ALL_STATUSES2) {
      statusSums[s] = { $sum: { $cond: [{ $eq: ["$status", s] }, 1, 0] } };
    }
    const agg = await Lead.aggregate([
      { $match: matchFilter },
      {
        $group: {
          _id: "$assignedTo",
          total: { $sum: 1 },
          ...statusSums
        }
      },
      {
        $lookup: {
          from: "users",
          localField: "_id",
          foreignField: "_id",
          as: "user"
        }
      },
      { $unwind: { path: "$user", preserveNullAndEmptyArrays: true } },
      {
        $project: {
          _id: 0,
          userId: "$_id",
          name: { $ifNull: ["$user.name", "Unassigned"] },
          email: { $ifNull: ["$user.email", ""] },
          designation: { $ifNull: ["$user.designation", ""] },
          total: 1,
          ...Object.fromEntries(ALL_STATUSES2.map((s) => [s, 1]))
        }
      }
    ]);
    const statsMap = new Map(agg.map((r) => [r.userId?.toString() ?? "", r]));
    const ZERO = Object.fromEntries(ALL_STATUSES2.map((s) => [s, 0]));
    const team = await Team.findById(teamId).populate("members", "name email designation").populate("inactiveMembers", "_id").lean();
    if (!team) {
      sendError(res, "Team not found", 404);
      return;
    }
    const inactiveSet = new Set(team.inactiveMembers.map((im) => im._id.toString()));
    const result = team.members.map((m) => {
      const uid = m._id?.toString() ?? "";
      const stats = statsMap.get(uid);
      return {
        userId: uid,
        name: m.name ?? "Unknown",
        email: m.email ?? "",
        designation: m.designation ?? "",
        isActive: !inactiveSet.has(uid),
        total: stats?.total ?? 0,
        ...stats ? Object.fromEntries(ALL_STATUSES2.map((s) => [s, stats[s] ?? 0])) : ZERO
      };
    }).sort((a, b) => b.total - a.total);
    sendSuccess(res, "Team member report fetched", result);
  } catch (err) {
    next(err);
  }
}
var TRACK_ACTIONS = [
  "lead_created",
  "lead_updated",
  "status_changed",
  "lead_assigned",
  "note_added",
  "call_made"
];
async function getTeamTracking(req, res, next) {
  try {
    const teamId = req.params.id;
    const { dateFrom, dateTo } = req.query;
    if (!import_mongoose12.default.isValidObjectId(teamId)) {
      sendError(res, "Invalid team id", 400);
      return;
    }
    const logDateFilter = {};
    if (dateFrom)
      logDateFilter.$gte = new Date(dateFrom + "T00:00:00.000+05:30");
    if (dateTo)
      logDateFilter.$lte = new Date(dateTo + "T23:59:59.999+05:30");
    const teamObjId = new import_mongoose12.default.Types.ObjectId(teamId);
    const basePipeline = [
      { $match: { team: teamObjId } },
      { $unwind: "$activityLogs" },
      ...Object.keys(logDateFilter).length ? [{ $match: { "activityLogs.createdAt": logDateFilter } }] : []
    ];
    const totalAgg = await Lead.aggregate([
      ...basePipeline,
      { $group: { _id: { user: "$activityLogs.performedBy", lead: "$_id" } } },
      { $group: { _id: "$_id.user", total: { $sum: 1 } } }
    ]);
    const actionAgg = await Lead.aggregate([
      ...basePipeline,
      { $group: { _id: { user: "$activityLogs.performedBy", lead: "$_id", action: "$activityLogs.action" } } },
      { $group: { _id: { user: "$_id.user", action: "$_id.action" }, count: { $sum: 1 } } },
      { $group: { _id: "$_id.user", actions: { $push: { action: "$_id.action", count: "$count" } } } }
    ]);
    const statusAgg = await Lead.aggregate([
      ...basePipeline,
      { $match: { "activityLogs.action": "status_changed" } },
      {
        $group: {
          _id: {
            user: "$activityLogs.performedBy",
            lead: "$_id",
            statusTo: "$activityLogs.changes.status.to"
          }
        }
      },
      { $group: { _id: { user: "$_id.user", statusTo: "$_id.statusTo" }, count: { $sum: 1 } } },
      { $group: { _id: "$_id.user", statuses: { $push: { status: "$_id.statusTo", count: "$count" } } } }
    ]);
    const totalMap = new Map(totalAgg.map((r) => [r._id?.toString() ?? "", r.total]));
    const actionMap = new Map(actionAgg.map((r) => [r._id?.toString() ?? "", r.actions]));
    const statusMap = new Map(statusAgg.map((r) => [r._id?.toString() ?? "", r.statuses]));
    const team = await Team.findById(teamId).populate("members", "name email designation").populate("inactiveMembers", "_id").lean();
    if (!team) {
      sendError(res, "Team not found", 404);
      return;
    }
    const inactiveSet = new Set(team.inactiveMembers.map((im) => im._id.toString()));
    const ZERO_ACTIONS = Object.fromEntries(TRACK_ACTIONS.map((a) => [a, 0]));
    const ZERO_STATUSES = Object.fromEntries(ALL_STATUSES2.map((s) => [`status_to_${s}`, 0]));
    const result = team.members.map((m) => {
      const uid = m._id?.toString() ?? "";
      const actions = actionMap.get(uid) ?? [];
      const statuses = statusMap.get(uid) ?? [];
      const actionObj = {
        ...ZERO_ACTIONS,
        ...Object.fromEntries(actions.map((a) => [a.action, a.count]))
      };
      const statusObj = {
        ...ZERO_STATUSES,
        ...Object.fromEntries(statuses.filter((s) => s.status).map((s) => [`status_to_${s.status}`, s.count]))
      };
      return {
        userId: uid,
        name: m.name ?? "Unknown",
        email: m.email ?? "",
        designation: m.designation ?? "",
        isActive: !inactiveSet.has(uid),
        total: totalMap.get(uid) ?? 0,
        ...actionObj,
        ...statusObj
      };
    }).sort((a, b) => b.total - a.total);
    sendSuccess(res, "Team tracking fetched", result);
  } catch (err) {
    next(err);
  }
}

