var syncSheetLeadsBatch = async (req, res, next) => {
  try {
    const rows = req.body?.rows;
    if (!Array.isArray(rows) || rows.length === 0) {
      sendError(res, '"rows" must be a non-empty array', 400);
      return;
    }
    if (rows.length > 200) {
      sendError(res, "Batch limit is 200 rows per request", 400);
      return;
    }
    const superAdmin = await User.findOne({ email: process.env.SUPER_ADMIN_EMAIL });
    if (!superAdmin) {
      sendError(res, "System reporter (Super Admin) not found", 500);
      return;
    }
    const reporterId = superAdmin._id.toString();
    const results = [];
    for (let i = 0;i < rows.length; i++) {
      const parsed2 = sheetRowSchema.safeParse(rows[i]);
      if (!parsed2.success) {
        results.push({
          index: i,
          status: "invalid",
          reason: JSON.stringify(parsed2.error.flatten().fieldErrors)
        });
        continue;
      }
      const row = parsed2.data;
      const phone2 = cleanPhone(row.phone_number);
      const email3 = row.email?.trim() || undefined;
      const exists = await Lead.findOne({ phone: phone2 });
      if (exists) {
        results.push({ index: i, status: "duplicate", leadId: exists._id.toString(), phone: phone2 });
        continue;
      }
      const noteContent = buildNote(row);
      const lead = await Lead.create({
        name: row.full_name.trim(),
        phone: phone2,
        email: email3,
        source: mapPlatformToSource(row.platform),
        platform: row.platform?.trim() || undefined,
        campaign: row.campaign_name?.trim() || undefined,
        status: "new",
        reporter: reporterId,
        notes: [
          {
            content: noteContent,
            author: reporterId,
            createdAt: new Date,
            updatedAt: new Date
          }
        ],
        activityLogs: [
          {
            action: "lead_created",
            description: `Lead imported from Google Sheets (${mapPlatformToSource(row.platform) === "whatsapp" ? "WhatsApp" : mapPlatformToSource(row.platform) === "google" ? "Google Ads" : "Facebook Ads"})`,
            performedBy: reporterId,
            createdAt: new Date
          }
        ]
      });
      results.push({ index: i, status: "created", leadId: lead._id.toString(), phone: phone2 });
    }
    const created = results.filter((r) => r.status === "created").length;
    const duplicate = results.filter((r) => r.status === "duplicate").length;
    const invalid = results.filter((r) => r.status === "invalid").length;
    let assigned = 0;
    const createdIds = results.filter((r) => r.status === "created" && r.leadId).map((r) => r.leadId);
    if (createdIds.length > 0) {
      try {
        const assignment = await leadService3.autoAssignLeads(createdIds);
        assigned = assignment.assigned;
      } catch {}
    }
    sendSuccess(res, `Batch processed: ${created} created, ${duplicate} skipped (duplicate), ${invalid} invalid`, {
      summary: { total: rows.length, created, duplicate, invalid, assignedToTeam: assigned },
      results
    }, 201);
  } catch (err) {
    next(err);
  }
};

