var renameAiSession = async (req, res) => {
  try {
    const userId = req.user.userId;
    const { sessionId } = req.params;
    const { sessionName } = req.body;
    if (!sessionName?.trim()) {
      sendError(res, "Session name is required", 400);
      return;
    }
    const updated = await AiMemory.findOneAndUpdate({ user: userId, sessionId }, { $set: { sessionName: sessionName.trim() } }, { new: true }).select("sessionId sessionName");
    if (!updated) {
      sendError(res, "Session not found", 404);
      return;
    }
    sendSuccess(res, "Session renamed", { sessionId: updated.sessionId, sessionName: updated.sessionName });
  } catch {
    sendError(res, "Failed to rename session", 500);
  }
};
var deleteAiSession = async (req, res) => {
  try {
    const userId = req.user.userId;
    const { sessionId } = req.params;
    const deleted = await AiMemory.findOneAndDelete({ user: userId, sessionId });
    if (!deleted) {
      sendError(res, "Session not found", 404);
      return;
    }
    sendSuccess(res, "Session deleted");
  } catch {
    sendError(res, "Failed to delete session", 500);
  }
};
